"""Summarize mailbox letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
REQUIRED = ("id", "from", "to", "status", "at")


def fields(path):
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    values = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            values[key] = value
    if any(not values.get(key) for key in REQUIRED):
        return None, "no_field"
    try:
        values["at"] = datetime.fromisoformat(values["at"])
    except ValueError:
        return None, "no_field"
    return values, None


def good_name(name):
    if not NAME.match(name):
        return False
    try:
        datetime.strptime(name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return False
    return True


def mailboxes(root):
    for box in sorted(root.iterdir(), key=lambda path: path.name):
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if not inbox.is_symlink() and inbox.is_dir():
            yield box.name, inbox


def summarize(root, now):
    boxes = {}
    candidates = []
    for name, inbox in mailboxes(root):
        boxes[name] = {"inbox": {}, "done": 0}
        for where, folder in (("inbox", inbox), ("done", inbox / "done")):
            if folder.is_symlink() or not folder.is_dir():
                continue
            for path in folder.iterdir():
                if (path.name.startswith(".") or path.suffix != ".md"
                        or path.is_symlink() or not path.is_file()):
                    continue
                relative = f"{name}/inbox/" + ("done/" if where == "done" else "") + path.name
                candidates.append((relative, path, name, where))

    bad = []
    letters = []
    seen = set()
    for relative, path, name, where in sorted(candidates, key=lambda item: item[0]):
        values, why = fields(path)
        if why is None and not good_name(path.name):
            why = "bad_name"
        if why is None and values["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(values["id"])
        letters.append((values, name, where))
        if where == "done":
            boxes[name]["done"] += 1
        else:
            counts = boxes[name]["inbox"]
            status = values["status"]
            counts[status] = counts.get(status, 0) + 1

    resolved = {values.get("re") for values, _, _ in letters
                if values["status"] in RESOLVING and values.get("re")}
    open_letters = []
    for values, _, where in letters:
        if values["status"] != "REQUEST" or values["id"] in resolved:
            continue
        at = values["at"]
        if at.tzinfo is None:
            at = at.replace(tzinfo=now.tzinfo)
        open_letters.append({"id": values["id"], "from": values["from"],
                             "to": values["to"], "where": where,
                             "age_min": (now - at) // timedelta(minutes=1)})
    open_letters.sort(key=lambda letter: (letter["to"], letter["id"]))
    bad.sort(key=lambda entry: (entry["file"], entry["why"]))
    return {"v": 1, "open": open_letters, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox TODO summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None or now.utcoffset() is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
